#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    char word[64];
    int count;
} WordFreq;

static int compareWordFreq(const void *a, const void *b) {
    const WordFreq *wa = (const WordFreq *)a;
    const WordFreq *wb = (const WordFreq *)b;
    if (wa->count != wb->count) {
        return wb->count - wa->count;
    }
    return strcmp(wa->word, wb->word);
}

char* sortWordsByFrequency(char* sentence) {
    if (!sentence) return NULL;

    int capacity = 1024;
    int count = 0;
    WordFreq *entries = (WordFreq *)malloc(capacity * sizeof(WordFreq));
    if (!entries) return NULL;

    char word[64];
    int wlen = 0;

    for (int i = 0; ; i++) {
        char c = sentence[i];
        if (c == ' ' || c == '\0') {
            if (wlen > 0) {
                word[wlen] = '\0';
                int found = 0;
                for (int j = 0; j < count; j++) {
                    if (strcmp(entries[j].word, word) == 0) {
                        entries[j].count++;
                        found = 1;
                        break;
                    }
                }
                if (!found) {
                    if (count >= capacity) {
                        capacity *= 2;
                        entries = (WordFreq *)realloc(entries, capacity * sizeof(WordFreq));
                    }
                    strcpy(entries[count].word, word);
                    entries[count].count = 1;
                    count++;
                }
                wlen = 0;
            }
            if (c == '\0') break;
        } else {
            if (wlen < 63) {
                word[wlen++] = (char)tolower((unsigned char)c);
            }
        }
    }

    qsort(entries, count, sizeof(WordFreq), compareWordFreq);

    size_t out_cap = 4096;
    char *result = (char *)malloc(out_cap);
    if (!result) {
        free(entries);
        return NULL;
    }
    result[0] = '\0';
    size_t cur_len = 0;

    char buf[128];
    for (int i = 0; i < count; i++) {
        int n = snprintf(buf, sizeof(buf), "%s%s(%d)", (i > 0 ? " " : ""), entries[i].word, entries[i].count);
        if (cur_len + n + 1 >= out_cap) {
            out_cap = (cur_len + n + 1) * 2;
            result = (char *)realloc(result, out_cap);
        }
        memcpy(result + cur_len, buf, n + 1);
        cur_len += n;
    }

    free(entries);
    return result;
}

