#include <cctype>

using namespace std;

class Solution {
public:
    string sortWordsByFrequency(string sentence) {
        unordered_map<string, int> freq;
        string word = "";
        for (char c : sentence) {
            if (c == ' ') {
                if (!word.empty()) {
                    freq[word]++;
                    word.clear();
                }
            } else {
                word += (char)tolower((unsigned char)c);
            }
        }
        if (!word.empty()) {
            freq[word]++;
        }

        vector<pair<string, int>> items(freq.begin(), freq.end());
        sort(items.begin(), items.end(), [](const pair<string, int>& a, const pair<string, int>& b) {
            if (a.second != b.second) {
                return a.second > b.second;
            }
            return a.first < b.first;
        });

        string result = "";
        for (size_t i = 0; i < items.size(); ++i) {
            if (i > 0) result += " ";
            result += items[i].first + "(" + to_string(items[i].second) + ")";
        }
        return result;
    }
};

